n=17; center=8
grid=[[0]*n for _ in range(n)]
for r in range(n):
    for c in (center-r, center+r):
        if 0 <= c < n: grid[r][c]=2
k=0
while True:
    d=center-4-4*k
    start=3+2*k
    # fill valid part of diagonal c-r=d for rows at/after its start
    for r in range(max(start,0,-d),n):
        c=r+d
        if 0<=c<n and grid[r][c]==0:
            grid[r][c]=1
    if start>=n and -d>=n: break
    k+=1
    if k>20: break
for row in grid: print(row)

